#!/usr/bin/env python3
"""seqfmt: quick format tools for FASTA/FASTQ with round-trip guarantees.

Subcommands:
    fq2fa        Convert FASTQ to FASTA.
    wrap N       Rewrap FASTA sequence lines to N columns.
    unwrap       Put each FASTA sequence on a single line.

Malformed FASTQ input fails with an error naming the record number.
"""

from __future__ import annotations

import argparse
import sys
from typing import Iterator, List, Tuple


class SeqFmtError(Exception):
    """Raised on malformed input. Message names the offending record."""


Record = Tuple[str, List[str]]  # (header, sequence lines)


# ---------------------------------------------------------------------------
# FASTA parsing / writing
# ---------------------------------------------------------------------------

def parse_fasta(text: str) -> List[Record]:
    """Parse FASTA text into a list of (header, [seq lines]) records.

    Sequence lines are joined-free: we return them as one string each via
    ''.join at write time; here we accumulate raw pieces.
    """
    records: List[Record] = []
    header: str | None = None
    chunks: List[str] = []

    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue  # tolerate blank lines between records
        if stripped.startswith(">"):
            if header is not None:
                records.append((header, ["".join(chunks)]))
            header = stripped[1:].strip()
            chunks = []
        else:
            if header is None:
                raise SeqFmtError(
                    f"line {lineno}: sequence data before any '>' header"
                )
            chunks.append(stripper(stripped))

    if header is not None:
        records.append((header, ["".join(chunks)]))
    return records


def stripper(s: str) -> str:
    # whitespace inside sequence lines is not expected; keep it strict
    return s.replace(" ", "")


def format_fasta(records: List[Record], width: int) -> str:
    """Format records with sequence wrapped to `width` columns (0 = one line)."""
    out: List[str] = []
    for header, seq_lines in records:
        seq = "".join(seq_lines)
        out.append(f">{header}")
        if width <= 0 or len(seq) == 0:
            out.append(seq)
        else:
            for i in range(0, len(seq), width):
                out.append(seq[i : i + width])
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------------------
# FASTQ parsing / conversion
# ---------------------------------------------------------------------------

def parse_fastq(text: str) -> List[Tuple[str, str]]:
    """Parse FASTQ into [(id, sequence), ...], validating every record."""
    lines = [ln.rstrip("\n").rstrip("\r") for ln in text.splitlines()]
    # drop trailing blank line(s)
    while lines and not lines[-1].strip():
        lines.pop()

    if not lines:
        return []

    if len(lines) % 4 != 0:
        raise SeqFmtError(
            f"FASTQ must have 4 lines per record; got {len(lines)} lines "
            f"(incomplete record {len(lines) // 4 + 1})"
        )

    records: List[Tuple[str, str]] = []
    for i in range(0, len(lines), 4):
        rec_no = i // 4 + 1
        head, seq, sep, qual = lines[i : i + 4]

        if not head.startswith("@"):
            raise SeqFmtError(
                f"record {rec_no}: expected '@' header line, got: {head!r}"
            )
        if not sep.startswith("+"):
            raise SeqFmtError(
                f"record {rec_no}: expected '+' separator line, got: {sep!r}"
            )
        if len(seq) != len(qual):
            raise SeqFmtError(
                f"record {rec_no}: sequence length {len(seq)} does not match "
                f"quality length {len(qual)}"
            )
        records.append((head[1:], seq))
    return records


def fastq_to_fasta(text: str, width: int = 0) -> str:
    """Convert FASTQ text to FASTA text. width=0 puts sequences on one line."""
    records = [(f"{ident}", [seq]) for ident, seq in parse_fastq(text)]
    return format_fasta(records, width)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main(argv: List[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="seqfmt", description="Quick FASTA/FASTQ formatting tools."
    )
    sub = parser.add_subparsers(dest="cmd", required=True)

    p_fq2fa = sub.add_parser("fq2fa", help="Convert FASTQ to FASTA.")
    p_fq2fa.add_argument("input", help="Input FASTQ file ('-' for stdin).")
    p_fq2fa.add_argument(
        "-w", "--width", type=int, default=0,
        help="Wrap output sequence lines to this many columns (default: one line).",
    )

    p_wrap = sub.add_parser("wrap", help="Rewrap FASTA sequence lines to N columns.")
    p_wrap.add_argument("width", type=int, help="Number of columns per line.")
    p_wrap.add_argument("input", help="Input FASTA file ('-' for stdin).")

    p_unwrap = sub.add_parser("unwrap", help="Put each FASTA sequence on one line.")
    p_unwrap.add_argument("input", help="Input FASTA file ('-' for stdin).")

    args = parser.parse_args(argv)

    def read_input(path: str) -> str:
        if path == "-":
            return sys.stdin.read()
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read()

    try:
        if args.cmd == "fq2fa":
            sys.stdout.write(fastq_to_fasta(read_input(args.input), args.width))
        elif args.cmd == "wrap":
            if args.width < 1:
                parser.error("width must be >= 1")
            records = parse_fasta(read_input(args.input))
            sys.stdout.write(format_fasta(records, args.width))
        elif args.cmd == "unwrap":
            records = parse_fasta(read_input(args.input))
            sys.stdout.write(format_fasta(records, 0))
    except SeqFmtError as exc:
        print(f"seqfmt: error: {exc}", file=sys.stderr)
        return 1
    except OSError as exc:
        print(f"seqfmt: error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

